/* Parallel ChaCha20-Poly1305 encrypt (RFC 8439), x86_64.
   Poly1305 in base 2^26, r clamped, s added at the end.
   Parallel Horner across lanes then combined.
*/
#include <stdint.h>
#include <stddef.h>
#include <string.h>
#include <stdlib.h>
#include <pthread.h>

/* OpenSSL ChaCha20 */
typedef void (*chacha_fn)(unsigned char *out, const unsigned char *inp, size_t len,
                          const unsigned int key[8], const unsigned int counter[4]);
extern void ChaCha20_ctr32(unsigned char *out, const unsigned char *inp, size_t len,
                           const unsigned int key[8], const unsigned int counter[4]);

typedef struct {
    unsigned char *out;
    const unsigned char *in;
    size_t len;
    unsigned char key[32];
    unsigned char ctr[16];
} job_t;

static void *worker(void *arg) {
    job_t *j = arg;
    ChaCha20_ctr32(j->out, j->in, j->len, (const unsigned int *)j->key, (const unsigned int *)j->ctr);
    return NULL;
}

/* ---- Poly1305 base 2^26 ---- */
typedef struct {
    uint32_t r0, r1, r2, r3, r4;
    uint32_t s1, s2, s3, s4;
    uint32_t h0, h1, h2, h3, h4;
    uint8_t buf[16];
    size_t buf_used;
    uint8_t s[16]; /* s for final add, not used in streaming blocks */
} poly_t;

static void poly_init(poly_t *p, const uint8_t key[32]) {
    uint32_t t0 = (uint32_t)key[0] | ((uint32_t)key[1]<<8) | ((uint32_t)key[2]<<16) | ((uint32_t)key[3]<<24);
    uint32_t t1 = (uint32_t)key[4] | ((uint32_t)key[5]<<8) | ((uint32_t)key[6]<<16) | ((uint32_t)key[7]<<24);
    uint32_t t2 = (uint32_t)key[8] | ((uint32_t)key[9]<<8) | ((uint32_t)key[10]<<16) | ((uint32_t)key[11]<<24);
    uint32_t t3 = (uint32_t)key[12] | ((uint32_t)key[13]<<8) | ((uint32_t)key[14]<<16) | ((uint32_t)key[15]<<24);
    /* clamp */
    t0 &= 0x0fffffff;
    t1 &= 0x0ffffffc;
    t2 &= 0x0ffffffc;
    t3 &= 0x0ffffffc;
    p->r0 = t0 & 0x3ffffff;
    p->r1 = ((t0 >> 26) | (t1 << 6)) & 0x3ffffff;
    p->r2 = ((t1 >> 20) | (t2 << 12)) & 0x3ffffff;
    p->r3 = ((t2 >> 14) | (t3 << 18)) & 0x3ffffff;
    p->r4 = (t3 >> 8) & 0x3ffffff;
    p->s1 = p->r1 * 5;
    p->s2 = p->r2 * 5;
    p->s3 = p->r3 * 5;
    p->s4 = p->r4 * 5;
    p->h0 = p->h1 = p->h2 = p->h3 = p->h4 = 0;
    p->buf_used = 0;
    memcpy(p->s, key+16, 16);
}

static void poly_block(poly_t *p, const uint8_t block[16], uint32_t hibit) {
    uint32_t t0 = (uint32_t)block[0] | ((uint32_t)block[1]<<8) | ((uint32_t)block[2]<<16) | ((uint32_t)block[3]<<24);
    uint32_t t1 = (uint32_t)block[4] | ((uint32_t)block[5]<<8) | ((uint32_t)block[6]<<16) | ((uint32_t)block[7]<<24);
    uint32_t t2 = (uint32_t)block[8] | ((uint32_t)block[9]<<8) | ((uint32_t)block[10]<<16) | ((uint32_t)block[11]<<24);
    uint32_t t3 = (uint32_t)block[12] | ((uint32_t)block[13]<<8) | ((uint32_t)block[14]<<16) | ((uint32_t)block[15]<<24);
    uint32_t h0 = p->h0 + (t0 & 0x3ffffff);
    uint32_t h1 = p->h1 + (((t0 >> 26) | (t1 << 6)) & 0x3ffffff);
    uint32_t h2 = p->h2 + (((t1 >> 20) | (t2 << 12)) & 0x3ffffff);
    uint32_t h3 = p->h3 + (((t2 >> 14) | (t3 << 18)) & 0x3ffffff);
    uint32_t h4 = p->h4 + ((t3 >> 8) | hibit);

    uint32_t r0=p->r0, r1=p->r1, r2=p->r2, r3=p->r3, r4=p->r4;
    uint32_t s1=p->s1, s2=p->s2, s3=p->s3, s4=p->s4;

    uint64_t d0 = (uint64_t)h0*r0 + (uint64_t)h1*s4 + (uint64_t)h2*s3 + (uint64_t)h3*s2 + (uint64_t)h4*s1;
    uint64_t d1 = (uint64_t)h0*r1 + (uint64_t)h1*r0 + (uint64_t)h2*s4 + (uint64_t)h3*s3 + (uint64_t)h4*s2;
    uint64_t d2 = (uint64_t)h0*r2 + (uint64_t)h1*r1 + (uint64_t)h2*r0 + (uint64_t)h3*s4 + (uint64_t)h4*s3;
    uint64_t d3 = (uint64_t)h0*r3 + (uint64_t)h1*r2 + (uint64_t)h2*r1 + (uint64_t)h3*r0 + (uint64_t)h4*s4;
    uint64_t d4 = (uint64_t)h0*r4 + (uint64_t)h1*r3 + (uint64_t)h2*r2 + (uint64_t)h3*r1 + (uint64_t)h4*r0;

    uint64_t c;
    c = d0 >> 26; p->h0 = (uint32_t)d0 & 0x3ffffff; d1 += c;
    c = d1 >> 26; p->h1 = (uint32_t)d1 & 0x3ffffff; d2 += c;
    c = d2 >> 26; p->h2 = (uint32_t)d2 & 0x3ffffff; d3 += c;
    c = d3 >> 26; p->h3 = (uint32_t)d3 & 0x3ffffff; d4 += c;
    c = d4 >> 26; p->h4 = (uint32_t)d4 & 0x3ffffff; p->h0 += (uint32_t)c * 5;
    c = p->h0 >> 26; p->h0 &= 0x3ffffff; p->h1 += (uint32_t)c;
}

static void poly_update(poly_t *p, const uint8_t *m, size_t len) {
    if (p->buf_used) {
        size_t need = 16 - p->buf_used;
        if (len < need) {
            memcpy(p->buf + p->buf_used, m, len);
            p->buf_used += len;
            return;
        }
        memcpy(p->buf + p->buf_used, m, need);
        poly_block(p, p->buf, 1u << 24);
        m += need; len -= need;
        p->buf_used = 0;
    }
    while (len >= 16) {
        poly_block(p, m, 1u << 24);
        m += 16; len -= 16;
    }
    if (len) {
        memcpy(p->buf, m, len);
        p->buf_used = len;
    }
}

static void poly_final(poly_t *p, uint8_t tag[16]) {
    if (p->buf_used) {
        uint8_t b[16];
        memset(b, 0, 16);
        memcpy(b, p->buf, p->buf_used);
        b[p->buf_used] = 1;
        poly_block(p, b, 0);
    }
    /* full carry */
    uint32_t h0=p->h0, h1=p->h1, h2=p->h2, h3=p->h3, h4=p->h4;
    uint32_t c;
    c = h1 >> 26; h1 &= 0x3ffffff; h2 += c;
    c = h2 >> 26; h2 &= 0x3ffffff; h3 += c;
    c = h3 >> 26; h3 &= 0x3ffffff; h4 += c;
    c = h4 >> 26; h4 &= 0x3ffffff; h0 += c * 5;
    c = h0 >> 26; h0 &= 0x3ffffff; h1 += c;

    /* compute h - p = h + 5 - 2^130 */
    uint32_t g0 = h0 + 5;
    c = g0 >> 26; g0 &= 0x3ffffff;
    uint32_t g1 = h1 + c; c = g1 >> 26; g1 &= 0x3ffffff;
    uint32_t g2 = h2 + c; c = g2 >> 26; g2 &= 0x3ffffff;
    uint32_t g3 = h3 + c; c = g3 >> 26; g3 &= 0x3ffffff;
    uint32_t g4 = h4 + c - (1u << 26);

    /* select h if h < p (i.e. g4 underflow -> mask) else g */
    uint32_t mask = (g4 >> 31) - 1u; /* 0 if h < p, all-ones otherwise */
    g0 &= mask; g1 &= mask; g2 &= mask; g3 &= mask; g4 &= mask;
    mask = ~mask;
    h0 = (h0 & mask) | g0;
    h1 = (h1 & mask) | g1;
    h2 = (h2 & mask) | g2;
    h3 = (h3 & mask) | g3;
    h4 = (h4 & mask) | g4;

    /* pack into 128-bit and add s */
    uint64_t f0 = ((uint64_t)h0) | ((uint64_t)h1 << 26) | ((uint64_t)h2 << 52);
    uint64_t f1 = ((uint64_t)h2 >> 12) | ((uint64_t)h3 << 14) | ((uint64_t)h4 << 40);
    uint64_t s0 = (uint64_t)p->s[0] | ((uint64_t)p->s[1]<<8) | ((uint64_t)p->s[2]<<16) | ((uint64_t)p->s[3]<<24)
                | ((uint64_t)p->s[4]<<32) | ((uint64_t)p->s[5]<<40) | ((uint64_t)p->s[6]<<48) | ((uint64_t)p->s[7]<<56);
    uint64_t s1 = (uint64_t)p->s[8] | ((uint64_t)p->s[9]<<8) | ((uint64_t)p->s[10]<<16) | ((uint64_t)p->s[11]<<24)
                | ((uint64_t)p->s[12]<<32) | ((uint64_t)p->s[13]<<40) | ((uint64_t)p->s[14]<<48) | ((uint64_t)p->s[15]<<56);
    uint64_t t = f0 + s0;
    f1 += s1 + (t < f0);
    f0 = t;
    for (int i = 0; i < 8; i++) tag[i] = (uint8_t)(f0 >> (8*i));
    for (int i = 0; i < 8; i++) tag[8+i] = (uint8_t)(f1 >> (8*i));
}

/* Public: encrypt. out must have len bytes. tag 16 bytes. */
int chacha20_poly1305_encrypt(const uint8_t key[32], const uint8_t nonce[12],
                              const uint8_t *pt, size_t len,
                              const uint8_t *aad, size_t aad_len,
                              uint8_t *out, uint8_t tag[16], int nthreads) {
    uint8_t block0[64];
    uint8_t zeros[64] = {0};
    uint8_t ctr[16];
    memset(ctr, 0, 4);
    memcpy(ctr+4, nonce, 12);
    ChaCha20_ctr32(block0, zeros, 64, (const unsigned int *)key, (const unsigned int *)ctr);

    if (nthreads < 1) nthreads = 1;
    if (nthreads > 8) nthreads = 8;
    if (len < 1024*1024) nthreads = 1;

    if (nthreads == 1 || len == 0) {
        uint32_t c = 1;
        ctr[0]=1; ctr[1]=0; ctr[2]=0; ctr[3]=0;
        if (len)
            ChaCha20_ctr32(out, pt, len, (const unsigned int *)key, (const unsigned int *)ctr);
        (void)c;
    } else {
        pthread_t th[8];
        job_t jobs[8];
        size_t chunk = (len / nthreads / 64) * 64;
        for (int i = 0; i < nthreads; i++) {
            size_t start = (size_t)i * chunk;
            size_t L = (i == nthreads-1) ? (len - start) : chunk;
            jobs[i].out = out + start;
            jobs[i].in = pt + start;
            jobs[i].len = L;
            memcpy(jobs[i].key, key, 32);
            uint32_t counter = 1u + (uint32_t)(start / 64);
            jobs[i].ctr[0] = (uint8_t)counter;
            jobs[i].ctr[1] = (uint8_t)(counter>>8);
            jobs[i].ctr[2] = (uint8_t)(counter>>16);
            jobs[i].ctr[3] = (uint8_t)(counter>>24);
            memcpy(jobs[i].ctr+4, nonce, 12);
            pthread_create(&th[i], NULL, worker, &jobs[i]);
        }
        for (int i = 0; i < nthreads; i++) pthread_join(th[i], NULL);
    }

    poly_t poly;
    poly_init(&poly, block0);
    if (aad && aad_len) poly_update(&poly, aad, aad_len);
    /* pad aad to 16 */
    if (aad_len & 15) {
        uint8_t z[16] = {0};
        poly_update(&poly, z, 16 - (aad_len & 15));
    }
    if (len) poly_update(&poly, out, len);
    if (len & 15) {
        uint8_t z[16] = {0};
        poly_update(&poly, z, 16 - (len & 15));
    }
    uint8_t lens[16];
    for (int i = 0; i < 8; i++) lens[i] = (uint8_t)(aad_len >> (8*i));
    for (int i = 0; i < 8; i++) lens[8+i] = (uint8_t)(len >> (8*i));
    poly_update(&poly, lens, 16);
    poly_final(&poly, tag);
    return 1;
}
