        c = d1 >> 26; hh[1] = (uint32_t)d1 & 0x3ffffff; d2 += c;
        c = d2 >> 26; hh[2] = (uint32_t)d2 & 0x3ffffff; d3 += c;
        c = d3 >> 26; hh[3] = (uint32_t)d3 & 0x3ffffff; d4 += c;
        c = d4 >> 26; hh[4] = (uint32_t)d4 & 0x3ffffff; hh[0] += (uint32_t)c * 5;
        c = hh[0] >> 26; hh[0] &= 0x3ffffff; hh[1] += (uint32_t)c;
