    }
    oh[0]=h0; oh[1]=h1; oh[2]=h2; oh[3]=h3; oh[4]=h4;
}

/* h = h + block, then * r. hibit is 1<<24 for full blocks, 0 for partial-with-0x01-already-in-block */
static void absorb_block(uint32_t *h,
                         uint32_t r0,uint32_t r1,uint32_t r2,uint32_t r3,uint32_t r4,
                         uint32_t s1,uint32_t s2,uint32_t s3,uint32_t s4,
                         const uint8_t block[16], uint32_t hibit) {
    uint32_t t0 = (uint32_t)block[0] | ((uint32_t)block[1]<<8) | ((uint32_t)block[2]<<16) | ((uint32_t)block[3]<<24);
    uint32_t t1 = (uint32_t)block[4] | ((uint32_t)block[5]<<8) | ((uint32_t)block[6]<<16) | ((uint32_t)block[7]<<24);
    uint32_t t2 = (uint32_t)block[8] | ((uint32_t)block[9]<<8) | ((uint32_t)block[10]<<16) | ((uint32_t)block[11]<<24);
    uint32_t t3 = (uint32_t)block[12] | ((uint32_t)block[13]<<8) | ((uint32_t)block[14]<<16) | ((uint32_t)block[15]<<24);
    uint32_t h0 = h[0] + (t0 & 0x3ffffff);
    uint32_t h1 = h[1] + (((t0 >> 26) | (t1 << 6)) & 0x3ffffff);
    uint32_t h2 = h[2] + (((t1 >> 20) | (t2 << 12)) & 0x3ffffff);
    uint32_t h3 = h[3] + (((t2 >> 14) | (t3 << 18)) & 0x3ffffff);
    uint32_t h4 = h[4] + ((t3 >> 8) | hibit);
    uint64_t d0 = (uint64_t)h0*r0 + (uint64_t)h1*s4 + (uint64_t)h2*s3 + (uint64_t)h3*s2 + (uint64_t)h4*s1;
    uint64_t d1 = (uint64_t)h0*r1 + (uint64_t)h1*r0 + (uint64_t)h2*s4 + (uint64_t)h3*s3 + (uint64_t)h4*s2;
    uint64_t d2 = (uint64_t)h0*r2 + (uint64_t)h1*r1 + (uint64_t)h2*r0 + (uint64_t)h3*s4 + (uint64_t)h4*s3;
    uint64_t d3 = (uint64_t)h0*r3 + (uint64_t)h1*r2 + (uint64_t)h2*r1 + (uint64_t)h3*r0 + (uint64_t)h4*s4;
    uint64_t d4 = (uint64_t)h0*r4 + (uint64_t)h1*r3 + (uint64_t)h2*r2 + (uint64_t)h3*r1 + (uint64_t)h4*r0;
    carry(d0,d1,d2,d3,d4, h);
}

/* Multiply two field elements (5x26 limbs). No hibit. */
static void mul_limbs(const uint32_t *a, const uint32_t *b, uint32_t *out) {
    uint32_t a0=a[0],a1=a[1],a2=a[2],a3=a[3],a4=a[4];
    uint32_t b0=b[0],b1=b[1],b2=b[2],b3=b[3],b4=b[4];
    uint32_t b1_5=b1*5, b2_5=b2*5, b3_5=b3*5, b4_5=b4*5;
    uint64_t d0 = (uint64_t)a0*b0 + (uint64_t)a1*b4_5 + (uint64_t)a2*b3_5 + (uint64_t)a3*b2_5 + (uint64_t)a4*b1_5;
    uint64_t d1 = (uint64_t)a0*b1 + (uint64_t)a1*b0 + (uint64_t)a2*b4_5 + (uint64_t)a3*b3_5 + (uint64_t)a4*b2_5;
    uint64_t d2 = (uint64_t)a0*b2 + (uint64_t)a1*b1 + (uint64_t)a2*b0 + (uint64_t)a3*b4_5 + (uint64_t)a4*b3_5;
    uint64_t d3 = (uint64_t)a0*b3 + (uint64_t)a1*b2 + (uint64_t)a2*b1 + (uint64_t)a3*b0 + (uint64_t)a4*b4_5;
    uint64_t d4 = (uint64_t)a0*b4 + (uint64_t)a1*b3 + (uint64_t)a2*b2 + (uint64_t)a3*b1 + (uint64_t)a4*b0;
    carry(d0,d1,d2,d3,d4, out);
}

static void add_limbs(uint32_t *dst, const uint32_t *src) {
    uint64_t d0 = (uint64_t)dst[0]+src[0];
    uint64_t d1 = (uint64_t)dst[1]+src[1];
    uint64_t d2 = (uint64_t)dst[2]+src[2];
    uint64_t d3 = (uint64_t)dst[3]+src[3];
    uint64_t d4 = (uint64_t)dst[4]+src[4];
    carry(d0,d1,d2,d3,d4, dst);
}

/* out = in * r^{exp} using square-and-multiply of the r element. r_limbs is r itself (not *5). */
static void mul_r_exp(const uint32_t *in, const uint32_t *r_limbs, size_t exp, uint32_t *out) {
    if (exp == 0) { memcpy(out, in, 5*sizeof(uint32_t)); return; }
    uint32_t base[5]; memcpy(base, r_limbs, sizeof(base));
    uint32_t acc[5]; int started = 0;
    uint32_t cur[5]; memcpy(cur, in, sizeof(cur));
    /* compute in * r^exp = in * (r^{exp}) */
    uint32_t rpow[5]; memcpy(rpow, r_limbs, sizeof(rpow));
    uint32_t result[5] = {1,0,0,0,0}; /* identity */
    size_t e = exp;
    uint32_t b[5]; memcpy(b, r_limbs, sizeof(b));
    while (e) {
        if (e & 1) {
            uint32_t tmp[5];
            mul_limbs(result, b, tmp);
            memcpy(result, tmp, sizeof(result));
        }
        uint32_t tmp[5];
        mul_limbs(b, b, tmp);
        memcpy(b, tmp, sizeof(tmp));
        e >>= 1;
    }
    mul_limbs(cur, result, out);
    (void)base; (void)acc; (void)started; (void)rpow;
}

static void *worker_main(void *arg) {
    worker_t *w = arg;
    pthread_mutex_lock(&w->mu);
    for (;;) {
        while (!w->has_job && !w->stop)
            pthread_cond_wait(&w->cv, &w->mu);
        if (w->stop) { pthread_mutex_unlock(&w->mu); return NULL; }
        unsigned char *out = w->out;
        const unsigned char *in = w->in;
        size_t len = w->len;
        unsigned char key[32], ctr[16];
        memcpy(key, w->key, 32);
        memcpy(ctr, w->ctr, 16);
        const unsigned char *mac = w->mac;
        size_t nblocks = w->nblocks;
        uint32_t r0=w->r0,r1=w->r1,r2=w->r2,r3=w->r3,r4=w->r4;
        uint32_t s1=w->s1,s2=w->s2,s3=w->s3,s4=w->s4;
        w->has_job = 0;
        pthread_mutex_unlock(&w->mu);

        if (len)
            ChaCha20_ctr32(out, in, len, (const unsigned int *)key, (const unsigned int *)ctr);
        uint32_t h[5] = {0,0,0,0,0};
        if (nblocks)
            poly_blocks(mac, nblocks, r0,r1,r2,r3,r4, s1,s2,s3,s4, h);

        pthread_mutex_lock(&w->mu);
        memcpy(w->out_h, h, sizeof(h));
        w->finished = 1;
        pthread_cond_signal(&w->done_cv);
    }
}

static void init_workers(void) {
    int n = 6;
    const char *e = getenv("CHACHA_THREADS");
    if (e) { int v = atoi(e); if (v>=1 && v<=MAX_T) n=v; }
    nworkers = n;
    for (int i = 0; i < n; i++) {
        worker_t *w = &workers[i];
        memset(w, 0, sizeof(*w));
        pthread_mutex_init(&w->mu, NULL);
        pthread_cond_init(&w->cv, NULL);
        pthread_cond_init(&w->done_cv, NULL);
        pthread_create(&w->th, NULL, worker_main, w);
    }
}

static void load_r(const uint8_t key[16], uint32_t *r0,uint32_t *r1,uint32_t *r2,uint32_t *r3,uint32_t *r4,
                   uint32_t *s1,uint32_t *s2,uint32_t *s3,uint32_t *s4) {
    uint32_t t0 = (uint32_t)key[0] | ((uint32_t)key[1]<<8) | ((uint32_t)key[2]<<16) | ((uint32_t)key[3]<<24);
    uint32_t t1 = (uint32_t)key[4] | ((uint32_t)key[5]<<8) | ((uint32_t)key[6]<<16) | ((uint32_t)key[7]<<24);
    uint32_t t2 = (uint32_t)key[8] | ((uint32_t)key[9]<<8) | ((uint32_t)key[10]<<16) | ((uint32_t)key[11]<<24);
    uint32_t t3 = (uint32_t)key[12] | ((uint32_t)key[13]<<8) | ((uint32_t)key[14]<<16) | ((uint32_t)key[15]<<24);
    t0 &= 0x0fffffff; t1 &= 0x0ffffffc; t2 &= 0x0ffffffc; t3 &= 0x0ffffffc;
    *r0 = t0 & 0x3ffffff;
    *r1 = ((t0 >> 26) | (t1 << 6)) & 0x3ffffff;
    *r2 = ((t1 >> 20) | (t2 << 12)) & 0x3ffffff;
    *r3 = ((t2 >> 14) | (t3 << 18)) & 0x3ffffff;
    *r4 = (t3 >> 8) & 0x3ffffff;
    *s1 = (*r1)*5; *s2 = (*r2)*5; *s3 = (*r3)*5; *s4 = (*r4)*5;
}

static void poly_final_from_h(uint32_t h0,uint32_t h1,uint32_t h2,uint32_t h3,uint32_t h4,
                              const uint8_t sbytes[16], uint8_t tag[16]) {
    uint32_t c;
    c = h1 >> 26; h1 &= 0x3ffffff; h2 += c;
    c = h2 >> 26; h2 &= 0x3ffffff; h3 += c;
    c = h3 >> 26; h3 &= 0x3ffffff; h4 += c;
    c = h4 >> 26; h4 &= 0x3ffffff; h0 += c * 5;
    c = h0 >> 26; h0 &= 0x3ffffff; h1 += c;
    uint32_t g0 = h0 + 5; c = g0 >> 26; g0 &= 0x3ffffff;
    uint32_t g1 = h1 + c; c = g1 >> 26; g1 &= 0x3ffffff;
    uint32_t g2 = h2 + c; c = g2 >> 26; g2 &= 0x3ffffff;
    uint32_t g3 = h3 + c; c = g3 >> 26; g3 &= 0x3ffffff;
    uint32_t g4 = h4 + c - (1u << 26);
    uint32_t mask = (g4 >> 31) - 1u;
    g0 &= mask; g1 &= mask; g2 &= mask; g3 &= mask; g4 &= mask;
    mask = ~mask;
    h0 = (h0 & mask) | g0;
    h1 = (h1 & mask) | g1;
    h2 = (h2 & mask) | g2;
    h3 = (h3 & mask) | g3;
    h4 = (h4 & mask) | g4;
    uint64_t f0 = ((uint64_t)h0) | ((uint64_t)h1 << 26) | ((uint64_t)h2 << 52);
    uint64_t f1 = ((uint64_t)h2 >> 12) | ((uint64_t)h3 << 14) | ((uint64_t)h4 << 40);
    uint64_t s0 = (uint64_t)sbytes[0] | ((uint64_t)sbytes[1]<<8) | ((uint64_t)sbytes[2]<<16) | ((uint64_t)sbytes[3]<<24)
                | ((uint64_t)sbytes[4]<<32) | ((uint64_t)sbytes[5]<<40) | ((uint64_t)sbytes[6]<<48) | ((uint64_t)sbytes[7]<<56);
    uint64_t s1v = (uint64_t)sbytes[8] | ((uint64_t)sbytes[9]<<8) | ((uint64_t)sbytes[10]<<16) | ((uint64_t)sbytes[11]<<24)
                | ((uint64_t)sbytes[12]<<32) | ((uint64_t)sbytes[13]<<40) | ((uint64_t)sbytes[14]<<48) | ((uint64_t)sbytes[15]<<56);
    uint64_t t = f0 + s0;
    f1 += s1v + (t < f0);
    f0 = t;
    for (int i = 0; i < 8; i++) tag[i] = (uint8_t)(f0 >> (8*i));
    for (int i = 0; i < 8; i++) tag[8+i] = (uint8_t)(f1 >> (8*i));
}

int chacha20_poly1305_encrypt(const uint8_t key[32], const uint8_t nonce[12],
                              const uint8_t *pt, size_t len,
                              const uint8_t *aad, size_t aad_len,
                              uint8_t *out, uint8_t tag[16], int nthreads) {
    uint8_t block0[64];
    uint8_t zeros[64] = {0};
    uint8_t ctr[16];
    memset(ctr, 0, 4);
    memcpy(ctr+4, nonce, 12);
    ChaCha20_ctr32(block0, zeros, 64, (const unsigned int *)key, (const unsigned int *)ctr);

    pthread_once(&once, init_workers);
    int nt = nworkers;
    if (nthreads > 0 && nthreads < nt) nt = nthreads;
    if (len < 256*1024 || len == 0) nt = 1;

    uint32_t r0,r1,r2,r3,r4,s1,s2,s3,s4;
    load_r(block0, &r0,&r1,&r2,&r3,&r4, &s1,&s2,&s3,&s4);
    uint32_t r_limbs[5] = {r0,r1,r2,r3,r4};

    if (nt == 1) {
        ctr[0] = 1;
        if (len)
            ChaCha20_ctr32(out, pt, len, (const unsigned int *)key, (const unsigned int *)ctr);
        uint32_t h[5] = {0,0,0,0,0};
        if (aad && aad_len) {
            size_t off=0;
            while (off+16<=aad_len) { absorb_block(h,r0,r1,r2,r3,r4,s1,s2,s3,s4, aad+off, 1u<<24); off+=16; }
            if (aad_len & 15) {
                uint8_t b[16]; memset(b,0,16); memcpy(b, aad+off, aad_len-off);
                absorb_block(h,r0,r1,r2,r3,r4,s1,s2,s3,s4, b, 1u<<24);
            }
        }
        if (len) {
            size_t full = len & ~(size_t)15;
            size_t off=0;
            while (off < full) {
                absorb_block(h,r0,r1,r2,r3,r4,s1,s2,s3,s4, out+off, 1u<<24);
                off += 16;
            }
            if (len & 15) {
                uint8_t b[16]; memset(b,0,16); memcpy(b, out+full, len-full); b[len-full]=1;
                absorb_block(h,r0,r1,r2,r3,r4,s1,s2,s3,s4, b, 0);
            }
        }
        uint8_t lens[16];
        for (int i=0;i<8;i++) lens[i]=(uint8_t)(aad_len>>(8*i));
        for (int i=0;i<8;i++) lens[8+i]=(uint8_t)(len>>(8*i));
        absorb_block(h,r0,r1,r2,r3,r4,s1,s2,s3,s4, lens, 1u<<24);
        poly_final_from_h(h[0],h[1],h[2],h[3],h[4], block0+16, tag);
        return 1;
    }

    size_t chunk = (len / nt / 64) * 64;
    for (int i = 0; i < nt; i++) {
        size_t start = (size_t)i * chunk;
        size_t L = (i == nt-1) ? (len - start) : chunk;
        size_t full = L & ~(size_t)15;
        worker_t *w = &workers[i];
        pthread_mutex_lock(&w->mu);
        w->out = out + start;
        w->in = pt + start;
        w->len = L;
        memcpy(w->key, key, 32);
        uint32_t counter = 1u + (uint32_t)(start / 64);
        w->ctr[0] = (uint8_t)counter;
        w->ctr[1] = (uint8_t)(counter>>8);
        w->ctr[2] = (uint8_t)(counter>>16);
        w->ctr[3] = (uint8_t)(counter>>24);
        memcpy(w->ctr+4, nonce, 12);
        w->mac = out + start;
        w->nblocks = full / 16;
        w->r0=r0; w->r1=r1; w->r2=r2; w->r3=r3; w->r4=r4;
        w->s1=s1; w->s2=s2; w->s3=s3; w->s4=s4;
        w->finished = 0;
        w->has_job = 1;
        pthread_cond_signal(&w->cv);
        pthread_mutex_unlock(&w->mu);
    }
    for (int i = 0; i < nt; i++) {
        worker_t *w = &workers[i];
        pthread_mutex_lock(&w->mu);
        while (!w->finished) pthread_cond_wait(&w->done_cv, &w->mu);
        pthread_mutex_unlock(&w->mu);
    }

    uint32_t h[5] = {0,0,0,0,0};
    if (aad && aad_len) {
        size_t off=0;
        while (off+16<=aad_len) { absorb_block(h,r0,r1,r2,r3,r4,s1,s2,s3,s4, aad+off, 1u<<24); off+=16; }
        if (aad_len & 15) {
            uint8_t b[16]; memset(b,0,16); memcpy(b, aad+off, aad_len-off);
            absorb_block(h,r0,r1,r2,r3,r4,s1,s2,s3,s4, b, 1u<<24);
        }
    }
    size_t total_full_blocks = len / 16;
    for (int i = 0; i < nt; i++) {
        size_t start = (size_t)i * chunk;
        size_t L = (i == nt-1) ? (len - start) : chunk;
        size_t nb = (L & ~(size_t)15) / 16;
        size_t blocks_after = total_full_blocks - (start/16) - nb;
        uint32_t shifted[5];
        mul_r_exp(workers[i].out_h, r_limbs, blocks_after, shifted);
        add_limbs(h, shifted);
    }
    if (len & 15) {
        uint8_t b[16]; memset(b,0,16); memcpy(b, out+(len & ~(size_t)15), len & 15); b[len & 15]=1;
        absorb_block(h,r0,r1,r2,r3,r4,s1,s2,s3,s4, b, 0);
    }
    uint8_t lens[16];
    for (int i=0;i<8;i++) lens[i]=(uint8_t)(aad_len>>(8*i));
    for (int i=0;i<8;i++) lens[8+i]=(uint8_t)(len>>(8*i));
    absorb_block(h,r0,r1,r2,r3,r4,s1,s2,s3,s4, lens, 1u<<24);
    poly_final_from_h(h[0],h[1],h[2],h[3],h[4], block0+16, tag);
    return 1;
}
