    if (len < 256 * 1024 || len == 0) nt = 1;

    if (nt == 1) {
        ctr[0] = 1;
        if (len)
            ChaCha20_ctr32(out, pt, len, (const unsigned int *)key, (const unsigned int *)ctr);
    } else {
        size_t chunk = (len / nt / 64) * 64;
        for (int i = 0; i < nt; i++) {
            size_t start = (size_t)i * chunk;
            size_t L = (i == nt - 1) ? (len - start) : chunk;
            worker_t *w = &workers[i];
            pthread_mutex_lock(&w->mu);
            w->out = out + start;
            w->in = pt + start;
            w->len = L;
            memcpy(w->key, key, 32);
            uint32_t counter = 1u + (uint32_t)(start / 64);
            w->ctr[0] = (uint8_t)counter;
            w->ctr[1] = (uint8_t)(counter >> 8);
            w->ctr[2] = (uint8_t)(counter >> 16);
            w->ctr[3] = (uint8_t)(counter >> 24);
            memcpy(w->ctr + 4, nonce, 12);
            w->finished = 0;
            w->has_job = 1;
            pthread_cond_signal(&w->cv);
            pthread_mutex_unlock(&w->mu);
        }
        for (int i = 0; i < nt; i++) {
            worker_t *w = &workers[i];
            pthread_mutex_lock(&w->mu);
            while (!w->finished) pthread_cond_wait(&w->done_cv, &w->mu);
            pthread_mutex_unlock(&w->mu);
        }
    }

    unsigned char pctx[512];
    Poly1305_Init(pctx, block0);
    if (aad && aad_len) Poly1305_Update(pctx, aad, aad_len);
    if (aad_len & 15) {
        uint8_t z[16] = {0};
        Poly1305_Update(pctx, z, 16 - (aad_len & 15));
    }
    if (len) Poly1305_Update(pctx, out, len);
    if (len & 15) {
        uint8_t z[16] = {0};
        Poly1305_Update(pctx, z, 16 - (len & 15));
    }
    uint8_t lens[16];
    for (int i = 0; i < 8; i++) lens[i] = (uint8_t)(aad_len >> (8 * i));
    for (int i = 0; i < 8; i++) lens[8 + i] = (uint8_t)(len >> (8 * i));
    Poly1305_Update(pctx, lens, 16);
    Poly1305_Final(pctx, tag);
    return 1;
}
