#include <stdio.h>
#include <stdint.h>
#include <string.h>
#include <stdlib.h>
#include <time.h>
extern void Poly1305_Init(void *ctx, const unsigned char key[32]);
extern void Poly1305_Update(void *ctx, const unsigned char *inp, size_t len);
extern void Poly1305_Final(void *ctx, unsigned char mac[16]);

static inline void carry5(uint64_t d0,uint64_t d1,uint64_t d2,uint64_t d3,uint64_t d4, uint32_t *h) {
    uint64_t c;
    c=d0>>26; h[0]=(uint32_t)d0 & 0x3ffffff; d1+=c;
    c=d1>>26; h[1]=(uint32_t)d1 & 0x3ffffff; d2+=c;
    c=d2>>26; h[2]=(uint32_t)d2 & 0x3ffffff; d3+=c;
    c=d3>>26; h[3]=(uint32_t)d3 & 0x3ffffff; d4+=c;
    c=d4>>26; h[4]=(uint32_t)d4 & 0x3ffffff; h[0]+=(uint32_t)c*5;
    c=h[0]>>26; h[0]&=0x3ffffff; h[1]+=(uint32_t)c;
}

/* process 4 blocks: h = (((h+m0)*r + m1)*r + m2)*r + m3)*r
   = (h+m0)*r^4 + m1*r^3 + m2*r^2 + m3*r
   We precompute r^2, r^3, r^4 and do one big product. For a first cut, just 4 sequential
   absorbs but with manual unroll to see compiler speed vs openssl. */
static void poly4_seq(const uint8_t *m, size_t nblocks, const uint32_t r[5], uint32_t h[5]) {
    uint32_t r0=r[0],r1=r[1],r2=r[2],r3=r[3],r4=r[4];
    uint32_t s1=r1*5,s2=r2*5,s3=r3*5,s4=r4*5;
    uint32_t h0=h[0],h1=h[1],h2=h[2],h3=h[3],h4=h[4];
    for (size_t i=0;i<nblocks;i++) {
        const uint8_t *b=m+i*16;
        uint32_t t0=(uint32_t)b[0]|((uint32_t)b[1]<<8)|((uint32_t)b[2]<<16)|((uint32_t)b[3]<<24);
        uint32_t t1=(uint32_t)b[4]|((uint32_t)b[5]<<8)|((uint32_t)b[6]<<16)|((uint32_t)b[7]<<24);
        uint32_t t2=(uint32_t)b[8]|((uint32_t)b[9]<<8)|((uint32_t)b[10]<<16)|((uint32_t)b[11]<<24);
        uint32_t t3=(uint32_t)b[12]|((uint32_t)b[13]<<8)|((uint32_t)b[14]<<16)|((uint32_t)b[15]<<24);
        h0 += t0 & 0x3ffffff;
        h1 += ((t0>>26)|(t1<<6)) & 0x3ffffff;
        h2 += ((t1>>20)|(t2<<12)) & 0x3ffffff;
        h3 += ((t2>>14)|(t3<<18)) & 0x3ffffff;
        h4 += (t3>>8) | (1u<<24);
        uint64_t d0=(uint64_t)h0*r0+(uint64_t)h1*s4+(uint64_t)h2*s3+(uint64_t)h3*s2+(uint64_t)h4*s1;
        uint64_t d1=(uint64_t)h0*r1+(uint64_t)h1*r0+(uint64_t)h2*s4+(uint64_t)h3*s3+(uint64_t)h4*s2;
        uint64_t d2=(uint64_t)h0*r2+(uint64_t)h1*r1+(uint64_t)h2*r0+(uint64_t)h3*s4+(uint64_t)h4*s3;
        uint64_t d3=(uint64_t)h0*r3+(uint64_t)h1*r2+(uint64_t)h2*r1+(uint64_t)h3*r0+(uint64_t)h4*s4;
        uint64_t d4=(uint64_t)h0*r4+(uint64_t)h1*r3+(uint64_t)h2*r2+(uint64_t)h3*r1+(uint64_t)h4*r0;
        uint64_t c;
        c=d0>>26; h0=(uint32_t)d0&0x3ffffff; d1+=c;
        c=d1>>26; h1=(uint32_t)d1&0x3ffffff; d2+=c;
        c=d2>>26; h2=(uint32_t)d2&0x3ffffff; d3+=c;
        c=d3>>26; h3=(uint32_t)d3&0x3ffffff; d4+=c;
        c=d4>>26; h4=(uint32_t)d4&0x3ffffff; h0+=(uint32_t)c*5;
        c=h0>>26; h0&=0x3ffffff; h1+=(uint32_t)c;
    }
    h[0]=h0;h[1]=h1;h[2]=h2;h[3]=h3;h[4]=h4;
}

int main() {
    size_t N=40960000;
    uint8_t *m=aligned_alloc(64, N);
    memset(m, 1, N);
    uint8_t key[32]; memset(key, 7, 32);
    /* fake r from key low */
    uint32_t r[5]={0x03ffffff,0x03ffff03,0x03ffc0ff,0x03f03fff,0x000fffff};
    uint32_t h[5]={0};
    size_t nb=N/16;
    poly4_seq(m, nb, r, h); /* warmup */
    struct timespec s,e;
    clock_gettime(CLOCK_MONOTONIC,&s);
    int IT=3;
    for(int i=0;i<IT;i++){ h[0]=h[1]=h[2]=h[3]=h[4]=0; poly4_seq(m, nb, r, h); }
    clock_gettime(CLOCK_MONOTONIC,&e);
    double w=(e.tv_sec-s.tv_sec)+(e.tv_nsec-s.tv_nsec)/1e9;
    printf("scalar poly %.4f MB/s %.0f h0=%u\n", w/IT, N/(w/IT)/1e6, h[0]);

    unsigned char ctx[512]; uint8_t tag[16];
    Poly1305_Init(ctx, key); Poly1305_Update(ctx, m, N); Poly1305_Final(ctx, tag);
    clock_gettime(CLOCK_MONOTONIC,&s);
    for(int i=0;i<IT;i++){ Poly1305_Init(ctx, key); Poly1305_Update(ctx, m, N); Poly1305_Final(ctx, tag); }
    clock_gettime(CLOCK_MONOTONIC,&e);
    w=(e.tv_sec-s.tv_sec)+(e.tv_nsec-s.tv_nsec)/1e9;
    printf("openssl poly %.4f MB/s %.0f\n", w/IT, N/(w/IT)/1e6);
    return 0;
}
EOF
