#include <stdio.h>
#include <stdint.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>
#define NT 6
typedef struct { uint8_t *dst, *src; size_t off, len; uint64_t k; } job;
static void *go(void *arg) {
    job *j = arg;
    uint64_t *d = (uint64_t *)(j->dst + j->off);
    uint64_t *s = (uint64_t *)(j->src + j->off);
    size_t n = j->len / 8;
    uint64_t k = j->k;
    for (size_t i = 0; i < n; i++) d[i] = s[i] ^ k;
    return NULL;
}
int main() {
    size_t N = 40960000;
    uint8_t *a = aligned_alloc(64, N);
    uint8_t *b = aligned_alloc(64, N);
    memset(a, 1, N);
    memset(b, 2, N);
    struct timespec s, e;
    int IT = 5;
    clock_gettime(CLOCK_MONOTONIC, &s);
    for (int it = 0; it < IT; it++) {
        pthread_t th[NT];
        job jobs[NT];
        size_t chunk = N / NT;
        for (int i = 0; i < NT; i++) {
            jobs[i].dst = b; jobs[i].src = a;
            jobs[i].off = (size_t)i * chunk;
            jobs[i].len = (i == NT-1) ? N - jobs[i].off : chunk;
            jobs[i].k = 0x0101010101010101ULL + it;
            pthread_create(&th[i], NULL, go, &jobs[i]);
        }
        for (int i = 0; i < NT; i++) pthread_join(th[i], NULL);
        a[0] = b[0];
    }
    clock_gettime(CLOCK_MONOTONIC, &e);
    double w = (e.tv_sec - s.tv_sec) + (e.tv_nsec - s.tv_nsec) / 1e9;
    printf("parallel xor (with thread create) %.4f s\n", w/IT);
    return 0;
}
